(43111, '_transient_newfold_notifications', 'a:2:{i:0;a:5:{s:2:\"id\";s:36:\"0e9d80c0-6efb-4596-871d-1998daae5cad\";s:9:\"locations\";a:1:{i:0;a:2:{s:5:\"pages\";s:3:\"all\";s:7:\"context\";s:15:\"wp-admin-notice\";}}s:5:\"query\";N;s:10:\"expiration\";i:1780285731;s:7:\"content\";s:19379:\"<style>.nfd-message-container {	margin: 10px 20px 0px auto;	clear: both;	position: relative;	container-type: inline-size;	container-name: nfd-message;	}	.nfd-root .nfd-message-container {	margin-right: 0px !important;	}	.nfd-message-container h1,	.nfd-message-container h2,	.nfd-message-container h3,	.nfd-message-container h4,	.nfd-message-container h5,	.nfd-message-container h6,	.nfd-message-container p {	margin: 0;	}	.nfd-message-container > div {	padding: 10px 45px 10px 20px;	min-height: 70px;	display: flex;	align-items: center;	}	@container nfd-message (max-width: 768px) {	.nfd-message-container > div {	padding: 16px;	}	}</style><div class=\"nfd-message-container\"><style>.nfd-message-container a[data-action=\"close\"] {	cursor: pointer;	z-index: 3;	position: absolute;	top: 12px;	right: 16px;	}</style><a href=\"\" data-action=\"close\" aria-label=\"Dismiss notice\" style=\"\"><svg width=\"14\" height=\"16\" viewBox=\"0 0 14 16\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><title>Dismiss</title><path	d=\"M14 1.58625L12.59 0L7 6.28875L1.41 0L0 1.58625L5.59 7.875L0 14.1637L1.41 15.75L7 9.46125L12.59 15.75L14 14.1637L8.41 7.875L14 1.58625Z\"	fill=\"#fff\" /></svg></a><style>.nfd-message-container-yoast {	background: linear-gradient(90.06deg, #5E247B -1.48%, #A71F6A 27.97%, #91216F 63.42%, #A71F6A 91.24%, #5E247B 107.6%);	color: #fff;	font-family: \"Open Sans\", sans-serif;	font-optical-sizing: auto;	display: flex;	justify-content: space-between;	align-items: center;	gap: 32px;	text-align: center;	border-radius: 8px;	box-shadow: 2px 4px 6px 0px rgba(0, 0, 0, 0.15);	}	.nfd-message-container-yoast > div:first-of-type {	min-width: 211px;	}	.nfd-message-container-yoast > div:last-of-type {	min-width: 125px;	}	.nfd-message-container-yoast div:last-of-type img {	display: none;	}	.nfd-message-container-yoast svg {	display: block;	margin: 0 auto;	}	.nfd-message-container-yoast p {	text-shadow: 2px 2px 8px rgba(0, 0, 0, .15);	}	@container nfd-message (max-width: 1040px) {	.nfd-message-container-yoast > div:first-of-type {	min-width: 175px;	}	}	@container nfd-message (max-width: 900px) {	.nfd-message-container-yoast svg {	scale: 0.9;	}	.nfd-message-container-yoast p {	font-size: 14px;	}	}	@container nfd-message (max-width: 768px) {	.nfd-message-container-yoast {	flex-direction: column;	gap: 16px;	}	.nfd-message-container-yoast > div:first-of-type {	display: none;	}	.nfd-message-container-yoast div:last-of-type {	min-width: 100%;	}	.nfd-message-container-yoast div:last-of-type img {	display: block;	max-width: 80px;	position: absolute;	top: 10px;	left: 16px;	}	}	@container nfd-message (max-width: 625px) {	.nfd-message-content {	padding-top: 32px;	}	.nfd-message-container-yoast div:last-of-type img {	max-width: 60px;	}	}</style><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:ital,wght@0,300..800;1,300..800&display=swap\" rel=\"stylesheet\"><div class=\"nfd-message-container-yoast\"><div><img src=\"https://d2k7nyq3ix8wzh.cloudfront.net/2262e98a-482d-40cc-9dfc-e8a1b69d741a/images/messages/yoast-seo-mascot-logo.png\" alt=\"Yoast logo\"></div><div class=\"nfd-message-content\"><div><svg width=\"269\" height=\"38\" viewBox=\"0 0 269 38\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M15.9766 21.6031C15.9766 23.8343 15.1797 25.5873 13.5861 26.8224C11.9924 28.0974 9.76125 28.7348 6.93248 28.7348C4.10371 28.7348 1.79288 28.2966 0 27.42V23.5554C1.15541 24.0733 2.35068 24.5116 3.62562 24.8303C4.90055 25.1491 6.09581 25.3084 7.21138 25.3084C8.84489 25.3084 10.0401 24.9897 10.7971 24.3921C11.5541 