(13, 1, '2025-05-31 10:06:03', '2025-05-31 10:06:03', '<!-- wp:group {\"metadata\":{\"name\":\"Heading\"},\"className\":\"nfd-container  nfd-wb-headings__heading-1 is-style-nfd-theme-white\",\"textColor\":\"white\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-container  nfd-wb-headings__heading-1 is-style-nfd-theme-white wp-block-group has-white-color has-text-color\"><!-- wp:cover {\"url\":\"https://images.unsplash.com/photo-1565120130276-dfbd9a7a3ad7?ixlib=rb-4.0.3\\u0026ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8\\u0026auto=format\\u0026fit=crop\\u0026q=80\\u0026w=1200\\u0026h=\\u0026crop=\",\"hasParallax\":true,\"dimRatio\":70,\"minHeight\":35,\"minHeightUnit\":\"vh\",\"contentPosition\":\"center center\",\"className\":\"nfd-p-lg nfd-bg-primary nfd-rounded-lg\",\"style\":{\"color\":[]}} -->\n<div class=\"nfd-p-lg nfd-bg-primary nfd-rounded-lg wp-block-cover has-parallax\" style=\"min-height:35vh\"><div class=\"wp-block-cover__image-background has-parallax\" style=\"background-position:50% 50%;background-image:url(https://images.unsplash.com/photo-1565120130276-dfbd9a7a3ad7?ixlib=rb-4.0.3&amp;ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&amp;auto=format&amp;fit=crop&amp;q=80&amp;w=1200&amp;h=&amp;crop=)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-70 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"align\":\"wide\",\"className\":\"nfd-container nfd-gap-md nfd-bg-surface nfd-theme-dark is-style-nfd-theme-dark\",\"style\":{\"color\":{\"background\":\"#ffffff00\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"nfd-container nfd-gap-md nfd-bg-surface nfd-theme-dark is-style-nfd-theme-dark wp-block-group alignwide has-background\" style=\"background-color:#ffffff00\"><!-- wp:paragraph {\"className\":\"nfd-text-xs nfd-text-balance\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"center\"}}} -->\n<p class=\"nfd-text-xs nfd-text-balance has-text-align-center\" style=\"font-style:normal;font-weight:600;text-transform:uppercase\">ABOUT OUR COMPANY</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance has-text-align-center\">We are a leading IT company in Cambodia, dedicated to delivering innovative software and application development solutions tailored to your business needs.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Call to Action\"},\"className\":\"nfd-container nfd-p-card-square-lg  nfd-wb-call-to-action__cta-13 is-style-nfd-theme-dark\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-container nfd-p-card-square-lg  nfd-wb-call-to-action__cta-13 is-style-nfd-theme-dark wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-xl\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"nfd-gap-xl wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-lg\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"left\"}} -->\n<div class=\"nfd-gap-lg wp-block-group\"><!-- wp:paragraph {\"className\":\"nfd-text-sm nfd-text-faded\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"500\",\"letterSpacing\":\"0.05em\",\"textAlign\":\"center\"}}} -->\n<p class=\"nfd-text-sm nfd-text-faded has-text-align-center\" style=\"font-style:normal;font-weight:500;letter-spacing:0.05em;text-transform:uppercase\">Unlock Your Potential</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"className\":\"wp-block-heading nfd-text-xl nfd-text-contrast nfd-text-balance\",\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<h2 class=\"wp-block-heading nfd-text-xl nfd-text-contrast nfd-text-balance has-text-align-left\">Transform Your Business with Our Innovative IT Solutions and Expertise in Software Development</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"md:nfd-items-start nfd-gap-md\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"md:nfd-items-start nfd-gap-md wp-block-group\"><!-- wp:buttons {\"className\":\"nfd-text-md\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\"}} -->\n<div class=\"nfd-text-md wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-xl \"} -->\n<div class=\"nfd-btn-xl  wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get Started Today!</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Text\"},\"className\":\"nfd-container nfd-text-md nfd-wb-text__text-7\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"nfd-container nfd-text-md nfd-wb-text__text-7 wp-block-group\"><!-- wp:group {\"metadata\":{\"name\":\"Paragraphs\"},\"className\":\"nfd-text-md\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"nfd-text-md wp-block-group\"><!-- wp:group {\"className\":\"nfd-max-w-prose\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\"}} -->\n<div class=\"nfd-max-w-prose wp-block-group\"><!-- wp:paragraph -->\n<p class=\"\">At our core, we are a dedicated IT company based in Cambodia, specializing in cutting-edge application and software development. Our mission is to empower businesses with innovative technology solutions that drive efficiency and growth. With a team of experienced professionals, we are committed to delivering high-quality services tailored to meet the unique needs of our clients.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p class=\"\">In an ever-evolving digital landscape, we understand the importance of staying ahead of the curve. Our expertise spans various domains, including mobile applications, web development, and enterprise software solutions. We pride ourselves on our ability to adapt and innovate, ensuring that our clients receive the most effective and up-to-date solutions available in the market.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://images.unsplash.com/photo-1565120130276-dfbd9a7a3ad7&amp;w=1024&amp;h=576&amp;crop=\" alt=\"\" style=\"aspect-ratio:16/9;object-fit:cover\"/><figcaption class=\"wp-element-caption\">Innovative IT Solutions for Your Business</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Paragraphs\"},\"className\":\"nfd-text-md\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"nfd-text-md wp-block-group\"><!-- wp:group {\"className\":\"nfd-max-w-prose\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\"}} -->\n<div class=\"nfd-max-w-prose wp-block-group\"><!-- wp:paragraph -->\n<p class=\"\">As we look to the future, our focus remains on fostering long-term partnerships with our clients. We believe that collaboration and communication are key to success, and we strive to create an environment where ideas can flourish. Together, we can navigate the complexities of technology and achieve remarkable results that propel your business forward.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"FAQ\"},\"className\":\"nfd-container nfd-p-lg  nfd-wb-faq__faq-4 is-style-nfd-theme-primary\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"lines\"} -->\n<div class=\"nfd-container nfd-p-lg  nfd-wb-faq__faq-4 is-style-nfd-theme-primary wp-block-group nfd-bg-effect-lines\"><!-- wp:columns {\"className\":\"nfd-gap-xl nfd-gap-y-2xl\"} -->\n<div class=\"nfd-gap-xl nfd-gap-y-2xl wp-block-columns\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:heading {\"className\":\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance\"} -->\n<h2 class=\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance\">Frequently Asked Questions</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:group {\"className\":\"nfd-grid nfd-grid-cols-2\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<div class=\"nfd-grid nfd-grid-cols-2 wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-y-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-y-xl wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-primary\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-primary\" style=\"font-style:normal;font-weight:500\">What services does your IT company offer?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">Our IT company specializes in application and software development, providing tailored solutions to meet the unique needs of businesses in Cambodia. We focus on delivering high-quality products that enhance operational efficiency and drive growth.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-primary\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-primary\" style=\"font-style:normal;font-weight:500\">How experienced is your team?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">Our team consists of highly skilled professionals with extensive experience in the IT industry. We have successfully completed numerous projects, leveraging the latest technologies to deliver innovative solutions that exceed client expectations.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-y-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-y-xl wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-primary\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-primary\" style=\"font-style:normal;font-weight:500\">What industries do you serve?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">We serve various industries, including finance, healthcare, and education, providing customized IT solutions to meet diverse business needs.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-primary\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-primary\" style=\"font-style:normal;font-weight:500\">Do you offer support services?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">Yes, we offer comprehensive support services to ensure our clients can effectively utilize our solutions. Our dedicated support team is available to assist with any issues or questions that may arise post-implementation.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-primary\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-primary\" style=\"font-style:normal;font-weight:500\">How can I get a quote for your services?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">To receive a quote for our services, please contact us through our website or call our office directly. We will discuss your project requirements and provide a detailed proposal tailored to your needs.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'About Us', '', 'publish', 'closed', 'closed', '', 'about-us', '', '', '2026-07-21 06:53:24', '2026-07-21 06:53:24', '', 0, 'https://gpe.ztf.mybluehost.me/about/', 0, 'page', '', 0);
