(16, 1, '2025-05-31 10:13:46', '2025-05-31 10:13:46', '<!-- wp:group {\"metadata\":{\"name\":\"Hero\"},\"align\":\"full\",\"className\":\"nfd-wb-hero__hero-7 is-style-nfd-theme-primary\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-wb-hero__hero-7 is-style-nfd-theme-primary wp-block-group alignfull\"><!-- wp:group {\"align\":\"full\",\"className\":\"nfd-p-lg nfd-container is-style-default\",\"style\":{\"color\":{\"gradient\":\"linear-gradient(120deg,rgba(7,146,227,0) 60%,rgba(0,0,0,0.24) 60%)\"}},\"layout\":{\"type\":\"constrained\"},\"nfdGroupEffect\":\"grid-3\"} -->\n<div class=\"nfd-p-lg nfd-container is-style-default wp-block-group alignfull has-background nfd-bg-effect-grid-3\" style=\"background:linear-gradient(120deg,rgba(7,146,227,0) 60%,rgba(0,0,0,0.24) 60%)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"nfd-py-md\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"50px\",\"left\":\"64px\"}}}} -->\n<div class=\"nfd-py-md wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\",\"style\":{\"spacing\":{\"blockGap\":\"50px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:45%\"><!-- wp:group {\"className\":\"nfd-text-md nfd-gap-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"nfd-text-md nfd-gap-xl wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"className\":\" nfd-rounded-full nfd-bg-subtle\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"16px\",\"left\":\"16px\",\"top\":\"6px\",\"bottom\":\"6px\"}}},\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\" nfd-rounded-full nfd-bg-subtle wp-block-group\" style=\"padding-top:6px;padding-right:16px;padding-bottom:6px;padding-left:16px\"><!-- wp:paragraph {\"className\":\"nfd-text-sm\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"600\"}}} -->\n<p class=\"nfd-text-sm\" style=\"font-style:normal;font-weight:600;text-transform:uppercase\">Experience in Hospital And Clinic applications</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"className\":\"nfd-text-giga nfd-text-contrast nfd-text-balance\"} -->\n<h1 class=\"nfd-text-giga nfd-text-contrast nfd-text-balance wp-block-heading has-text-align-left\">Transforming Ideas into Innovative Software Solutions</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"className\":\"nfd-text-balance nfd-text-faded\"} -->\n<p class=\"nfd-text-balance nfd-text-faded has-text-align-left\">At our professional IT company in Cambodia, we specialize in delivering cutting-edge application and software development services tailored to your business needs. Our expert team is dedicated to providing technology solutions that drive success and efficiency.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"nfd-gap-xl nfd-gap-y-md\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"nfd-gap-xl nfd-gap-y-md wp-block-group\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-xl\"} -->\n<div class=\"nfd-btn-xl wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get Started Today</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-base nfd-text-faded\"} -->\n<p class=\"nfd-text-base nfd-text-faded\">Join us on a journey to elevate your business with our custom software solutions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"55%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:55%\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":59,\"width\":\"421px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/advancedmd-lifestyle-docMobileEHR-scaled.png?fit=1024%2C900&amp;ssl=1\" alt=\"\" class=\"wp-image-59\" style=\"aspect-ratio:1;object-fit:cover;width:421px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":66,\"width\":\"184px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"is-style-default wp-block-image size-full is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/iotworlds-development-of-an-app.png?fit=750%2C500&amp;ssl=1\" alt=\"\" class=\"wp-image-66\" style=\"aspect-ratio:1;object-fit:cover;width:184px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Features\"},\"className\":\"nfd-container nfd-p-lg  nfd-wb-features__features-5 is-style-nfd-theme-white\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-container nfd-p-lg  nfd-wb-features__features-5 is-style-nfd-theme-white wp-block-group\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"nfd-text-base nfd-gap-3xl\"} -->\n<div class=\"nfd-text-base nfd-gap-3xl wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"className\":\"md:nfd-order-2 nfd-text-md\",\"style\":{\"spacing\":{\"blockGap\":\"24px\"}}} -->\n<div class=\"md:nfd-order-2 nfd-text-md wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"nfd-gap-lg\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-lg wp-block-group\"><!-- wp:heading {\"className\":\"nfd-text-xl nfd-text-contrast nfd-text-balance\"} -->\n<h2 class=\"nfd-text-xl nfd-text-contrast nfd-text-balance wp-block-heading\">Empowering Your Digital Future</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-balance\"} -->\n<p class=\"nfd-text-balance\">Our expert team delivers innovative software and application solutions tailored to your business needs, ensuring growth and efficiency in the digital landscape.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-lg \"} -->\n<div class=\"nfd-btn-lg  wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Discover Our Services</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"nfd-grid nfd-grid-cols-9 nfd-grid-rows-1 nfd-items-center\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"nfd-grid nfd-grid-cols-9 nfd-grid-rows-1 nfd-items-center wp-block-group\"><!-- wp:image {\"aspectRatio\":\"2/3\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"nfd-col-start-1 nfd-col-end-7 nfd-row-start-1 nfd-rounded\"} -->\n<figure class=\"nfd-col-start-1 nfd-col-end-7 nfd-row-start-1 nfd-rounded wp-block-image size-large\"><img src=\"https://images.unsplash.com/photo-1565120130276-dfbd9a7a3ad7?ixlib=rb-4.0.3&amp;ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTJ8fHJlc3RhdXJhbnR8ZW58MHwxfDB8fA%3D%3D&amp;auto=format&amp;fit=crop&amp;q=60&amp;w=800&amp;h=&amp;crop=\" alt=\"\" style=\"aspect-ratio:2/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"aspectRatio\":\"2/3\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"nfd-col-start-5 nfd-col-end-13 nfd-row-start-1 nfd-border-bg nfd-rounded\",\"style\":{\"border\":{\"left\":{\"width\":\"3px\"}}}} -->\n<figure class=\"nfd-col-start-5 nfd-col-end-13 nfd-row-start-1 nfd-border-bg nfd-rounded wp-block-image size-large has-custom-border\"><img src=\"https://images.unsplash.com/photo-1547860664-b8537ca5f833?ixlib=rb-4.0.3&amp;ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTF8fHJlc3RhdXJhbnR8ZW58MHwxfDB8fA%3D%3D&amp;auto=format&amp;fit=crop&amp;q=60&amp;w=800&amp;h=&amp;crop=\" alt=\"\" style=\"border-left-width:3px;aspect-ratio:2/3;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-container nfd-wb-testimonials__testimonials-10\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"nfd-container nfd-wb-testimonials__testimonials-10 wp-block-group\"><!-- wp:columns 