:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"nfd-my-0 nfd-container nfd-pt-md nfd-pb-lg\",\"style\":{\"spacing\":{\"blockGap\":\"80px\"}},\"backgroundColor\":\"white\",\"textColor\":\"black\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"nfd-my-0 nfd-container nfd-pt-md nfd-pb-lg wp-block-group alignfull has-black-color has-white-background-color has-text-color has-background\" id=\"testimonials\"><!-- wp:group {\"className\":\"nfd-gap-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"nfd-gap-xl wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"className\":\"nfd-text-contrast nfd-text-giga nfd-text-balance\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h2 class=\"nfd-text-contrast nfd-text-giga nfd-text-balance wp-block-heading has-text-align-center\" style=\"font-style:normal;font-weight:500\">What our customers say</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"className\":\"nfd-rounded-lg nfd-overflow-hidden\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"0\"},\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"nfd-rounded-lg nfd-overflow-hidden wp-block-columns\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column {\"verticalAlignment\":\"stretch\",\"width\":\"\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:100%\"><!-- wp:image {\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"classN