(72, 1, '2025-06-07 03:11:49', '2025-06-07 03:11:49', '<!-- wp:group {\"metadata\":{\"name\":\"Hero\"},\"align\":\"full\",\"className\":\"nfd-wb-hero__hero-7 is-style-nfd-theme-primary\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-wb-hero__hero-7 is-style-nfd-theme-primary wp-block-group alignfull\"><!-- wp:group {\"align\":\"full\",\"className\":\"nfd-p-lg nfd-container is-style-default\",\"style\":{\"color\":{\"gradient\":\"linear-gradient(120deg,rgba(7,146,227,0) 60%,rgba(0,0,0,0.24) 60%)\"}},\"layout\":{\"type\":\"constrained\"},\"nfdGroupEffect\":\"grid-3\"} -->\n<div class=\"nfd-p-lg nfd-container is-style-default wp-block-group alignfull has-background nfd-bg-effect-grid-3\" style=\"background:linear-gradient(120deg,rgba(7,146,227,0) 60%,rgba(0,0,0,0.24) 60%)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"nfd-py-md\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"50px\",\"left\":\"64px\"}}}} -->\n<div class=\"nfd-py-md wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"45%\",\"style\":{\"spacing\":{\"blockGap\":\"50px\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:45%\"><!-- wp:group {\"className\":\"nfd-text-md nfd-gap-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"left\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"nfd-text-md nfd-gap-xl wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"className\":\" nfd-rounded-full nfd-bg-subtle\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"16px\",\"left\":\"16px\",\"top\":\"6px\",\"bottom\":\"6px\"}}},\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\" nfd-rounded-full nfd-bg-subtle wp-block-group\" style=\"padding-top:6px;padding-right:16px;padding-bottom:6px;padding-left:16px\"><!-- wp:paragraph {\"className\":\"nfd-text-sm\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\",\"fontStyle\":\"normal\",\"fontWeight\":\"600\"}}} -->\n<p class=\"nfd-text-sm\" style=\"font-style:normal;font-weight:600;text-transform:uppercase\">Experience in Hospital And Clinic applications</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"level\":1,\"className\":\"nfd-text-giga nfd-text-contrast nfd-text-balance\"} -->\n<h1 class=\"nfd-text-giga nfd-text-contrast nfd-text-balance wp-block-heading has-text-align-left\">Transforming Ideas into Innovative Software Solutions</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"className\":\"nfd-text-balance nfd-text-faded\"} -->\n<p class=\"nfd-text-balance nfd-text-faded has-text-align-left\">At our professional IT company in Cambodia, we specialize in delivering cutting-edge application and software development services tailored to your business needs. Our expert team is dedicated to providing technology solutions that drive success and efficiency.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"nfd-gap-xl nfd-gap-y-md\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"nfd-gap-xl nfd-gap-y-md wp-block-group\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-xl\"} -->\n<div class=\"nfd-btn-xl wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Get Started Today</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-base nfd-text-faded\"} -->\n<p class=\"nfd-text-base nfd-text-faded\">Join us on a journey to elevate your business with our custom software solutions.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"55%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:55%\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":59,\"width\":\"421px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/advancedmd-lifestyle-docMobileEHR-scaled.png?fit=1024%2C900&amp;ssl=1\" alt=\"\" class=\"wp-image-59\" style=\"aspect-ratio:1;object-fit:cover;width:421px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":66,\"width\":\"184px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"is-style-default wp-block-image size-full is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/iotworlds-development-of-an-app.png?fit=750%2C500&amp;ssl=1\" alt=\"\" class=\"wp-image-66\" style=\"aspect-ratio:1;object-fit:cover;width:184px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"right\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":64,\"width\":\"undefinedpx\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\"} -->\n<figure class=\"is-style-default wp-block-image size-full is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/istockphoto-1193278024-612x612-1.jpg?fit=612%2C320&amp;ssl=1\" alt=\"\" class=\"wp-image-64\" style=\"aspect-ratio:1;object-fit:cover;width:undefinedpx\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":68,\"width\":\"undefinedpx\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"https://i0.wp.com/gpe.ztf.mybluehost.me/wp-content/uploads/2025/06/Future-of-Mobile-App-Development.jpg?fit=934%2C660&amp;ssl=1\" alt=\"\" class=\"wp-image-68\" style=\"aspect-ratio:1;object-fit:cover;width:undefinedpx\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Features\"},\"className\":\"nfd-container nfd-p-lg  nfd-wb-features__features-5 is-style-nfd-theme-white\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-container nfd-p-lg  nfd-wb-features__features-5 is-style-nfd-theme-white wp-block-group\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"className\":\"nfd-text-base nfd-gap-3xl\"} -->\n<div class=\"nfd-text-base nfd-gap-3xl wp-block-columns are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"className\":\"md:nfd-order-2 nfd-text-md\",\"style\":{\"spacing\":{\"blockGap\":\"24px\"}}} -->\n<div class=\"md:nfd-order-2 nfd-text-md wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"nfd-gap-lg\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-lg wp-block-group\"><!-- wp:heading {\"className\":\"nfd-text-xl nfd-text-contrast nfd-text-balance\"} -->\n<h2 class=\"nfd-text-xl nfd-text-contrast nfd-text-balance wp-block-heading\">Empowering Your Digital Future</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-balance\"} -->\n<p class=\"nfd-text-balance\">Our expert team delivers innovative software and application solutions tailored to your business needs, ensuring growth and efficiency in the digital landscape.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\",\"flexWrap\":\"wrap\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-lg \"} -->\n<div class=\"nfd-btn-lg  wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Discover Our Services</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:group {\"className\":\"nfd-grid nfd-grid-cols-9 nfd-grid-rows-1 nfd-items-center\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"nfd-grid nfd-grid-cols-9 nfd-grid-rows-1 nfd-items-center wp-block-group\"><!-- wp:image {\"aspectRatio\":\"2/3\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"nfd-col-start-1 nfd-col-end-7 nfd-row-start-1 nfd-rounded\"} -->\n<figure class=\"nfd-col-start-1 nfd-col-end-7 nfd-row-start-1 nfd-rounded wp-block-image size-large\"><img src=\"https://images.unsplash.com/photo-1565120130276-dfbd9a7a3ad7?ixlib=rb-4.0.3&amp;ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTJ8fHJlc3RhdXJhbnR8ZW58MHwxfDB8fA%3D%3D&amp;auto=format&amp;fit=crop&amp;q=60&amp;w=800&amp;h=&amp;crop=\" alt=\"\" style=\"aspect-ratio:2/3;object-fit:cover\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"aspectRatio\":\"2/3\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"className\":\"nfd-col-start-5 nfd-col-end-13 nfd-row-start-1 nfd-border-bg nfd-rounded\",\"style\":{\"border\":{\"left\":{\"width\":\"3px\"}}}} -->\n<figure class=\"nfd-col-start-5 nfd-col-end-13 nfd-row-start-1 nfd-border-bg nfd-rounded wp-block-image size-large has-custom-border\"><img src=\"https://images.unsplash.com/photo-1547860664-b8537ca5f833?ixlib=rb-4.0.3&amp;ixid=MnwxMjA3fDB8MHxzZWFyY2h8MTF8fHJlc3RhdXJhbnR8ZW58MHwxfDB8fA%3D%3D&amp;auto=format&amp;fit=crop&amp;q=60&amp;w=800&amp;h=&amp;crop=\" alt=\"\" style=\"border-left-width:3px;aspect-ratio:2/3;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-container nfd-wb-testimonials__testimonials-10\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"nfd-container nfd-wb-testimonials__testimonials-10 wp-block-group\"><!-- wp:columns {\"className\":\"nfd-rounded-lg nfd-overflow-hidden\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\",\"left\":\"0\"},\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"nfd-rounded-lg nfd-overflow-hidden wp-block-columns\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column {\"verticalAlignment\":\"stretch\",\"width\":\"\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"style\":{\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\" style=\"min-height:100%\"><!-- wp:image {\"id\":58,\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"nfd-h-full nfd-w-full\",\"style\":{\"layout\":{\"selfStretch\":\"fixed\",\"flexSize\":\"100%\"}}} -->\n<figure class=\"nfd-h-full nfd-w-full wp-block-image size-large\"><img src=\"http://localhost:3000/wp-content/uploads/2025/06/advancedmd-lifestyle-docMobileEHR-1024x900.webp\" alt=\"\" class=\"wp-image-58\" style=\"aspect-ratio:1;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"stretch\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}}} -->\n<div class=\"wp-block-column is-vertically-aligned-stretch\"><!-- wp:group {\"className\":\"nfd-text-lg nfd-p-card-lg nfd-bg-surface nfd-theme-dark is-style-nfd-theme-dark\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"lineHeight\":\"1.3\"},\"dimensions\":{\"minHeight\":\"100%\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-text-lg nfd-p-card-lg nfd-bg-surface nfd-theme-dark is-style-nfd-theme-dark wp-block-group\" style=\"min-height:100%;font-style:normal;font-weight:400;line-height:1.3\"><!-- wp:group {\"className\":\"nfd-text-balance\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-text-balance wp-block-group\"><!-- wp:paragraph {\"className\":\"nfd-text-md\",\"style\":{\"color\":{\"text\":\"#fab906\"},\"typography\":{\"letterSpacing\":\"2px\"}}} -->\n<p class=\"nfd-text-md has-text-color\" style=\"color:#fab906;letter-spacing:2px\">We are inspired from real problem</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p class=\"\">Health is really the priority for everyone. The same goes with our Cambodian people.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"className\":\"nfd-text-md nfd-gap-0\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-text-md nfd-gap-0 wp-block-group\"><!-- wp:paragraph -->\n<p class=\"\">Together we commit for the better!!!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-sm nfd-text-faded\"} -->\n<p class=\"nfd-text-sm nfd-text-faded\">Better health for Cambodian</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Call to Action\"},\"className\":\"nfd-container nfd-p-md  nfd-wb-call-to-action__cta-23 is-style-nfd-theme-darker\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\"} -->\n<div class=\"nfd-container nfd-p-md  nfd-wb-call-to-action__cta-23 is-style-nfd-theme-darker wp-block-group\"><!-- wp:group {\"className\":\"nfd-p-card-md nfd-gap-xl nfd-shadow-xs nfd-bg-surface nfd-theme-dark nfd-rounded is-style-nfd-theme-dark\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"\"} -->\n<div class=\"nfd-p-card-md nfd-gap-xl nfd-shadow-xs nfd-bg-surface nfd-theme-dark nfd-rounded is-style-nfd-theme-dark wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-md\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"nfd-gap-md wp-block-group\"><!-- wp:image {\"id\":32,\"width\":\"65px\",\"height\":\"auto\",\"aspectRatio\":\"1\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\"} -->\n<figure class=\"is-style-rounded wp-block-image size-full is-resized\"><img src=\"http://localhost:3000/wp-content/uploads/2025/05/IMG_2538-1-green-1-1.webp\" alt=\"\" class=\"wp-image-32\" style=\"aspect-ratio:1;object-fit:cover;width:65px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:group {\"className\":\"nfd-gap-0\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-0 wp-block-group\"><!-- wp:paragraph {\"className\":\"nfd-text-md\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\"}}} -->\n<p class=\"nfd-text-md\" style=\"font-style:normal;font-weight:600\">How can we assist you today?</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-base nfd-text-faded\"} -->\n<p class=\"nfd-text-base nfd-text-faded\">Our team is here to provide tailored solutions for your needs. Reach out to us for expert guidance!</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"nfd-btn-wide \"} -->\n<div class=\"nfd-btn-wide  wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Engage in a chat</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"FAQ\"},\"className\":\"nfd-container nfd-p-lg  nfd-wb-faq__faq-3 is-style-nfd-theme-darker\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"grid-3\"} -->\n<div class=\"nfd-container nfd-p-lg  nfd-wb-faq__faq-3 is-style-nfd-theme-darker wp-block-group nfd-bg-effect-grid-3\"><!-- wp:columns {\"className\":\"nfd-gap-xl nfd-gap-y-2xl\"} -->\n<div class=\"nfd-gap-xl nfd-gap-y-2xl wp-block-columns\"><!-- wp:column {\"width\":\"45%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:45%\"><!-- wp:heading {\"className\":\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance\"} -->\n<h2 class=\"wp-block-heading nfd-text-huge nfd-text-contrast nfd-text-balance\">Frequently Asked Questions</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:group {\"className\":\"nfd-grid nfd-grid-cols-2\",\"style\":{\"spacing\":{\"blockGap\":\"40px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"top\"}} -->\n<div class=\"nfd-grid nfd-grid-cols-2 wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-y-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-y-xl wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-contrast\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-contrast\" style=\"font-style:normal;font-weight:500\">What is your company’s mission?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">Our mission is to provide innovative technology solutions that empower businesses in Cambodia to achieve their goals through effective software and application development.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-contrast\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-contrast\" style=\"font-style:normal;font-weight:500\">How can I get a quote for my project?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">To receive a quote, please contact us with your project details, and our team will respond promptly with a tailored proposal based on your requirements.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-y-xl\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-y-xl wp-block-group\"><!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-contrast\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-contrast\" style=\"font-style:normal;font-weight:500\">What industries do you serve?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">We serve various industries including finance, healthcare, education, and retail, providing customized solutions that cater to each sector\'s specific needs.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-contrast\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-contrast\" style=\"font-style:normal;font-weight:500\">Do you provide ongoing support?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">Yes, we offer ongoing support and maintenance services to ensure your applications run smoothly and efficiently after deployment.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"nfd-gap-sm wp-block-group\"><!-- wp:heading {\"level\":3,\"className\":\"wp-block-heading nfd-text-md nfd-text-contrast\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"}}} -->\n<h3 class=\"wp-block-heading nfd-text-md nfd-text-contrast\" style=\"font-style:normal;font-weight:500\">What services do you offer?</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"nfd-text-faded nfd-text-base\"} -->\n<p class=\"nfd-text-faded nfd-text-base\">We offer a wide range of services including custom software development, mobile application development, web development, and IT consulting tailored to meet the unique needs of our clients in Cambodia.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"40px\",\"style\":{\"layout\":[]}} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Blog\"},\"className\":\"nfd-container nfd-p-lg  nfd-wb-blog__blog-8 is-style-nfd-theme-dark\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"\",\"nfdGroupEffect\":\"grid-2\"} -->\n<div class=\"nfd-container nfd-p-lg  nfd-wb-blog__blog-8 is-style-nfd-theme-dark wp-block-group nfd-bg-effect-grid-2\"><!-- wp:query {\"queryId\":14,\"query\":{\"perPage\":\"3\",\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"author\":\"\",\"search\":\"\",\"exclude\":[],\"sticky\":\"exclude\",\"inherit\":false},\"className\":\"nfd-query-loop-1\"} -->\n<div class=\"nfd-query-loop-1 wp-block-query\"><!-- wp:post-template {\"className\":\"nfd-gap-xl\",\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"1\",\"height\":\"\",\"className\":\"nfd-rounded-md\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"24px\"}}}} /-->\n\n<!-- wp:group {\"className\":\"nfd-text-sm\",\"style\":{\"spacing\":{\"blockGap\":\"8px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"left\"}} -->\n<div class=\"nfd-text-sm wp-block-group\"><!-- wp:post-author {\"showAvatar\":false,\"byline\":\"By \"} /-->\n\n<!-- wp:group {\"style\":{\"color\":{\"text\":\"#ffffff70\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-text-color\" style=\"color:#ffffff70\"><!-- wp:paragraph -->\n<p class=\"\">/</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:post-terms {\"term\":\"category\",\"prefix\":\"In \",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|white\"},\":hover\":{\"color\":{\"text\":\"var:preset|color|secondary\"}}}},\"color\":{\"text\":\"#ffffffcc\"}}} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:post-title {\"level\":3,\"isLink\":true,\"className\":\"nfd-text-md nfd-text-contrast nfd-text-balance\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"500\"},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} /-->\n<!-- /wp:post-template --></div>\n<!-- /wp:query --></div>\n<!-- /wp:group -->', 'Home', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2025-06-07 03:11:49', '2025-06-07 03:11:49', '', 16, 'https://gpe.ztf.mybluehost.me/?p=72', 0, 'revision', '', 0);
